class CategoryItem {
  final int id;
  final String group; // 'expense' | 'income' | 'asset' | 'liability' | 'equity' | 'cash'
  final String code;
  final String name;
  final String icon;
  final int? parentId;
  final String? parentName;
  final bool isHeader;

  const CategoryItem({
    required this.id,
    required this.group,
    required this.code,
    required this.name,
    required this.icon,
    this.parentId,
    this.parentName,
    this.isHeader = false,
  });

  String get displayName => icon.isNotEmpty ? ' ' : name;
}

