  static List<CategoryItem> get expenses =>
      all.where((c) => c.group == 'expense').toList();

  static List<CategoryItem> get selectableExpenses =>
      all.where((c) => c.group == 'expense' && !c.isHeader).toList();

  static List<CategoryItem> get incomes =>
      all.where((c) => c.group == 'income').toList();

  static List<CategoryItem> get selectableIncomes =>
      all.where((c) => c.group == 'income' && !c.isHeader).toList();

  static CategoryItem? findById(int id) {
    try {
      return all.firstWhere((c) => c.id == id);
    } catch (_) {
      return null;
    }
  }

  static CategoryItem? findByName(String name) {
    try {
      return all.firstWhere((c) => c.name == name);
    } catch (_) {
      return null;
    }
  }
